"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["53221"],{68971(e){e.exports=JSON.parse('{"id":"V4-162","slug":"scope-1-emissions","term":"Scope 1 Emissions","also_known_as":[],"difficulty":"Intermediate","definition":"Scope 1 emissions are the greenhouse gas emissions that come directly from sources owned or controlled by an organisation, such as fuel burned in its boilers, furnaces and vehicles.","explanation":["The Greenhouse Gas Protocol, the most widely used standard for measuring corporate emissions, divides emissions into three scopes. Scope 1 covers direct emissions from the organisation\u2019s own operations.","Sources of Scope 1 emissions include burning fuels on site, such as gas for heating; fuel used by company-owned or controlled vehicles; industrial processes that release greenhouse gases, such as cement or chemical production; and leaks of refrigerant gases from air conditioning.","For example, a delivery company\u2019s Scope 1 emissions would include the diesel burned by its fleet of trucks. A steel company\u2019s Scope 1 emissions would include emissions from its blast furnaces.","Scope 1 emissions are usually the easiest to measure and the most directly under a company\u2019s control. They are included in most mandatory climate reporting requirements. Companies can reduce them by switching to cleaner fuels, electrifying vehicles and equipment, improving energy efficiency and changing industrial processes. For heavy industry and energy companies, Scope 1 emissions often make up a large share of their total footprint."],"note":"","total":1725,"prev":{"slug":"scenario-analysis","term":"Scenario Analysis"},"next":{"slug":"scope-2-emissions","term":"Scope 2 Emissions"}}')}}]);